#!/usr/bin/env bash
# MEDfl client setup for the site "{{.SiteID}}", generated by MEDomics on {{.GeneratedAt}}.
#
# Run it once on the client Mac, as the user who will run the agent (without sudo):   bash {{.FileName}}
#
# It joins the study Tailscale network, installs the MEDfl agent in ~/medfl and starts it now and at every login.
# It contains the join key and the study token of this site: do not share it with other sites.
set -euo pipefail

SITE_ID="{{.SiteID}}"
COORDINATOR="{{.CoordinatorIP}}"
PORT="{{.Port}}"
AUTH_KEY="{{.AuthKey}}"
TOKEN="{{.Token}}"

info() { echo "[MEDfl] $*"; }
fail() { echo "[MEDfl] ERROR: $*" >&2; exit 1; }

[ "$(id -u)" -ne 0 ] || fail "run this script without sudo: bash $0"
BASE="$HOME/medfl"

# ---------- 1. Tailscale ----------
TS=""
for cand in /Applications/Tailscale.app/Contents/MacOS/Tailscale "$(command -v tailscale || true)"; do
  if [ -n "$cand" ] && [ -x "$cand" ]; then
    TS="$cand"
    break
  fi
done
[ -n "$TS" ] || fail "install Tailscale from https://tailscale.com/download/mac, open it once, then run this script again"
if "$TS" status >/dev/null 2>&1; then
  info "Tailscale is already connected."
elif [ -n "$AUTH_KEY" ]; then
  info "Joining the study network..."
  "$TS" up --authkey "$AUTH_KEY" --hostname "$SITE_ID" || fail "tailscale up failed: the join key may be used or expired, ask the coordinator for a new script"
else
  info "Sign in to the study network with the link below (accept the coordinator's invitation first)."
  "$TS" up --hostname "$SITE_ID"
fi

# ---------- 2. Python 3.10 to 3.12 ----------
find_python() {
  for cand in python3.12 python3.11 python3.10 /opt/homebrew/bin/python3.12 /usr/local/bin/python3.12 python3; do
    if command -v "$cand" >/dev/null 2>&1 && "$cand" -c 'import sys; sys.exit(0 if (3, 10) <= sys.version_info[:2] <= (3, 12) else 1)' 2>/dev/null; then
      command -v "$cand"
      return 0
    fi
  done
  return 1
}
PYTHON="$(find_python || true)"
if [ -z "$PYTHON" ] && command -v brew >/dev/null 2>&1; then
  info "Installing Python 3.12 with Homebrew..."
  brew install python@3.12
  PYTHON="$(find_python || true)"
fi
[ -n "$PYTHON" ] || fail "Python 3.10, 3.11 or 3.12 is required: install it from https://www.python.org/downloads/macos/, then run this script again"
info "Using $PYTHON"

# ---------- 3. Agent ----------
mkdir -p "$BASE/data" "$BASE/logs"
info "Downloading the MEDfl agent from the coordinator ($COORDINATOR)..."
for i in $(seq 1 30); do
  if curl -fsS "http://$COORDINATOR:$PORT/medfl/agent/medfl_agent.py" -o "$BASE/medfl_agent.py"; then
    break
  fi
  [ "$i" -eq 30 ] && fail "cannot reach the coordinator at $COORDINATOR:$PORT: check that MEDomics is open on the coordinator and that this Mac is in the study network"
  sleep 2
done
cat >"$BASE/medfl_agent.json" <<EOF
{
  "ctrl_url": "ws://$COORDINATOR:$PORT/medfl/rw/ws/agent",
  "agent_id": "$SITE_ID",
  "base_dir": "$BASE",
  "token": "$TOKEN"
}
EOF
chmod 600 "$BASE/medfl_agent.json"

# ---------- 4. Start at login ----------
LABEL="org.medomics.medfl-agent.$SITE_ID"
PLIST="$HOME/Library/LaunchAgents/$LABEL.plist"
mkdir -p "$HOME/Library/LaunchAgents"
cat >"$PLIST" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>$LABEL</string>
  <key>ProgramArguments</key>
  <array><string>$PYTHON</string><string>$BASE/medfl_agent.py</string></array>
  <key>WorkingDirectory</key><string>$BASE</string>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>StandardOutPath</key><string>$BASE/logs/agent.out.log</string>
  <key>StandardErrorPath</key><string>$BASE/logs/agent.out.log</string>
</dict>
</plist>
EOF
launchctl bootout "gui/$(id -u)/$LABEL" 2>/dev/null || true
launchctl bootstrap "gui/$(id -u)" "$PLIST"
info "The agent runs in the background (launchctl list | grep medfl)."

info "Done."
info "Put the site's files in $BASE/data: dataset.csv (training) and, for the holdout test, holdout.csv."
info "The first start installs MEDfl (10 to 20 minutes). Follow it with: tail -f $BASE/logs/agent.log"
